import{_ as t,o as d,c as a,a2 as o}from"./chunks/framework.DoCD98hS.js";const u=JSON.parse('{"title":"3D 场景 · three.js、二维动效与三维 UI","description":"","frontmatter":{},"headers":[],"relativePath":"modules/catalog/3d.md","filePath":"modules/catalog/3d.md","lastUpdated":1795336342000}'),s={name:"modules/catalog/3d.md"};function i(r,e,c,h,l,n){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="_3d-场景-·-three-js、二维动效与三维-ui" tabindex="-1">3D 场景 · three.js、二维动效与三维 UI <a class="header-anchor" href="#_3d-场景-·-three-js、二维动效与三维-ui" aria-label="Permalink to &quot;3D 场景 · three.js、二维动效与三维 UI&quot;">​</a></h1><p>一组从 threeui 复刻的视觉远程包：<code>comps-vue3-3d</code> 用 three.js 渲染三维场景，<code>comps-vue3-2d</code> 承接 Canvas 2D 与内嵌 HTML/CSS 动效，<code>comps-vue3-3dui</code> 承接 DOM UI 件与裸 WebGL 特效。three 随 <code>comps-vue3-3d</code> 打进 bundle，宿主不需要单独安装 three；另外两个包不依赖 three。</p><blockquote><p>组件复刻自开源 <a href="https://threeui.com" target="_blank" rel="noreferrer">threeui</a>：源码仓库 <a href="https://github.com/MengTo/threeui" target="_blank" rel="noreferrer">MengTo/threeui</a>（npm <code>@designcodeio/threeui</code> 1.2.0），上游许可证 MIT License，Copyright (c) 2026 Meng To。MIT 为宽松协议，无 copyleft 传染性；三个包都只复刻渲染逻辑（纯 three 核心 API 或原生 Canvas / CSS），未引入上游素材、字体或贴图。</p></blockquote><h2 id="包范围" tabindex="-1">包范围 <a class="header-anchor" href="#包范围" aria-label="Permalink to &quot;包范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包名</th><th>职责</th></tr></thead><tbody><tr><td><code>@melt-js/comps-vue3-3d</code></td><td>三维场景：three.js 场景、粒子与轨道渲染</td></tr><tr><td><code>@melt-js/comps-vue3-2d</code></td><td>二维动效：<code>getContext(&#39;2d&#39;)</code> 画布动画与内嵌 HTML/CSS 动效</td></tr><tr><td><code>@melt-js/comps-vue3-3dui</code></td><td>三维 UI 件：按钮 / CTA / 徽章 / 开关 / 面板 / 文字动画与裸 WebGL 特效</td></tr></tbody></table><p><code>comps-vue3-2d</code> 早期叫 <code>comps-vue3-canvas</code>，改名后与 <code>comps-vue3-3d</code>、<code>comps-vue3-3dui</code> 形成「2d / 3d / 3dui」的命名对仗；旧名不再作为独立包提供。</p><h2 id="在线演示" tabindex="-1">在线演示 <a class="header-anchor" href="#在线演示" aria-label="Permalink to &quot;在线演示&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模板 / 示例</th><th>演示地址</th></tr></thead><tbody><tr><td><code>demo-vue3-3d</code></td><td><a href="https://unpkg.com/@melt-js/demo-vue3-3d/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr></tbody></table><p>一个宿主同时消费三个包、六个页面（简介 / 轨道球体背景 / 二维加载器 / 凝露气泡背景 / 三维 UI 徽章 / 流光 CTA 按钮），页面清单与预加载写法见<a href="./../demos-3d.html">3D 演示</a>。</p><h2 id="提供的组件" tabindex="-1">提供的组件 <a class="header-anchor" href="#提供的组件" aria-label="Permalink to &quot;提供的组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>组件</th><th>用途</th></tr></thead><tbody><tr><td><code>comps-vue3-3d</code></td><td><code>OrbitalSphereBackground</code></td><td>轨道球体粒子背景：斐波那契球面分布粒子点云、六条倾斜轨道线与轨道小球光晕，进入可视区才渲染，随视口宽度切换机位</td></tr><tr><td><code>comps-vue3-2d</code></td><td><code>UplinkLoader</code></td><td>上行链路加载指示器（当前占位实现）</td></tr><tr><td><code>comps-vue3-2d</code></td><td><code>CondensationBackground</code></td><td>凝露气泡背景：气泡生长、成熟下落、合并与水滴尾迹</td></tr><tr><td><code>comps-vue3-3dui</code></td><td><code>SparkBadge</code></td><td>火花徽章（当前占位实现）</td></tr><tr><td><code>comps-vue3-3dui</code></td><td><code>LumenCta</code></td><td>流光 CTA 按钮：纯 DOM + CSS，primary / ghost 变体与 dark / light 模式</td></tr></tbody></table><p>三个包按上游组件清单逐步扩充，当前 3d 一个、2d 两个、3dui 两个；面板可调的 Props 以各包 <code>propsSchema.json</code> 为准。</p><h2 id="接入方式" tabindex="-1">接入方式 <a class="header-anchor" href="#接入方式" aria-label="Permalink to &quot;接入方式&quot;">​</a></h2><p>宿主先 <code>bindVueRuntime({ Vue })</code> 绑定自身 Vue，再预加载需要的包，从包根具名导入组件；包根是空壳代理，不包含组件实现。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { OrbitalSphereBackground } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@melt-js/comps-vue3-3d&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { UplinkLoader } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@melt-js/comps-vue3-2d&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { SparkBadge } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@melt-js/comps-vue3-3dui&#39;</span></span></code></pre></div><ul><li><code>OrbitalSphereBackground</code> 容器默认占满父级宽高，使用时给父元素确定尺寸即可；</li><li>WebGL 上下文创建失败时降级为占位提示，不会中断宿主页面；</li><li>三个包可以分开接入：只用二维加载器就只加载 <code>comps-vue3-2d</code>，不必把 three 一起拉下来。</li></ul>`,16)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
